class Solution {
public:
    string longestDiverseString(int a, int b, int c) {
        string res;
        int cnt[3] = {a, b, c};
        char ch[3] = {'a', 'b', 'c'};
        while (true) {
            int best = -1;
            int n = res.size();
            for (int i = 0; i < 3; i++) {
                if (cnt[i] == 0) continue;
                if (n >= 2 && res[n - 1] == ch[i] && res[n - 2] == ch[i]) continue;
                if (best == -1 || cnt[i] > cnt[best]) best = i;
            }
            if (best == -1) break;
            res.push_back(ch[best]);
            cnt[best]--;
        }
        return res;
    }
};
